WITH kept_keys AS (SELECT country FROM suppliers INTERSECT SELECT country FROM suppliers WHERE LENGTH(supplier_name) > 9), reconciled AS (SELECT s.* FROM suppliers s INNER JOIN kept_keys k ON s.country = k.country), eligible AS (SELECT s.* FROM reconciled s WHERE NOT EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND MONTH(x.launch_date) IN (3, 6, 8))), enriched AS (SELECT id, supplier_name, DENSE_RANK() OVER (PARTITION BY city ORDER BY rating NULLS LAST) AS rating_dense_rank FROM eligible), with_windows AS (SELECT *, CUME_DIST() OVER (ORDER BY rating_dense_rank DESC NULLS LAST) AS rating_dense_rank_cume_dist, PERCENT_RANK() OVER w_part AS rating_dense_rank_percent_rank FROM enriched WHERE rating_dense_rank BETWEEN 3 AND 7 WINDOW w_part AS (ORDER BY rating_dense_rank NULLS LAST)) SELECT CASE WHEN rating_dense_rank >= 8 THEN 'LARGE' ELSE 'SMALL' END AS rating_dense_rank_tier, CASE WHEN rating_dense_rank_cume_dist >= 0.77 THEN 'HIGH' ELSE 'LOW' END AS rating_dense_rank_cume_dist_tier, COUNT(*) AS row_count, ROUND(AVG(rating_dense_rank_cume_dist), 2) AS avg_rating_dense_rank_cume_dist, PERCENTILE_APPROX(rating_dense_rank_percent_rank, 0.95) AS rating_dense_rank_percent_rank_p95 FROM with_windows GROUP BY ROLLUP (CASE WHEN rating_dense_rank >= 8 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN rating_dense_rank_cume_dist >= 0.77 THEN 'HIGH' ELSE 'LOW' END)
